def read_with_repair(replicas: list, key: str, async_pool) -> dict | None:
    if len(replicas) < 2:
        raise ValueError('Quorum R=2 requires at least 2 replicas')
    primary = replicas[0].get_full(key)  # includes tombstone flag + HLC
    peer_digest = replicas[1].get_digest(key)
    if primary['digest'] == peer_digest:
        return None if primary.get('tombstone') else primary['value']
    peer = replicas[1].get_full(key)
    winner = max([primary, peer], key=lambda r: (r['hlc_ms'], r['hlc_seq'], r['node_id']))
    for rep, rec in zip(replicas[:2], [primary, peer]):
        if rec['digest'] != winner['digest']:
            async_pool.submit(rep.put_if_newer, key, winner)
    return None if winner.get('tombstone') else winner['value']
